"""Curated quiz catalog: 100 practical questions for each track."""


def _make_questions(section, concepts):
    questions = []
    for number, (concept, prompt, answer, explanation) in enumerate(concepts, 1):
        difficulty = "easy" if number <= 50 else "medium" if number <= 80 else "hard"
        questions.append({
            "section": section,
            "number": number,
            "difficulty": difficulty,
            "title": concept,
            "prompt": prompt,
            "answer": answer,
            "explanation": explanation,
        })
    return questions


