BEGINNER_EXERCISES = {
    "List comprehension": {
        "prompt": "Write a function that returns the squares of even numbers in nums.",
        "examples": [{"input": "nums = [1, 2, 3, 4, 5, 6]", "output": "[4, 16, 36]"}, {"input": "nums = [7, 9]", "output": "[]"}],
        "starter_code": "def even_squares(nums):\n    # Write your solution here\n    pass",
        "solution_code": "def even_squares(nums):\n    return [number ** 2 for number in nums if number % 2 == 0]",
        "test_cases": [{"args": [[1, 2, 3, 4, 5, 6]], "expected": [4, 16, 36]}, {"args": [[7, 9]], "expected": []}],
        "hints": ["Look at each number one at a time.", "Use a loop and an if condition, then square values that pass.", "Pseudocode: create an empty result; for each number, if it is even, append its square."],
        "tags": ["lists", "loops", "conditions"], "function_name": "even_squares",
    },
    "Dictionary counting": {
        "prompt": "Write a function that returns how many times each value appears in values.",
        "examples": [{"input": "values = ['a', 'b', 'a', 'c', 'b', 'a']", "output": "{'a': 3, 'b': 2, 'c': 1}"}],
        "starter_code": "def count_values(values):\n    # Write your solution here\n    pass",
        "solution_code": "def count_values(values):\n    counts = {}\n    for value in values:\n        counts[value] = counts.get(value, 0) + 1\n    return counts",
        "test_cases": [{"args": [["a", "b", "a", "c", "b", "a"]], "expected": {"a": 3, "b": 2, "c": 1}}, {"args": [[]], "expected": {}}],
        "hints": ["Keep one running total for each distinct value.", "A dictionary can map a value to its current count.", "For each value, read its old count or zero, add one, then return the dictionary."],
        "tags": ["dictionaries", "loops", "counting"], "function_name": "count_values",
    },
    "Safe dictionary lookup": {
        "prompt": "Write a function that returns the value for key from settings, or default when key is absent.",
        "examples": [{"input": "settings = {'mode': 'test'}, key = 'timeout', default = 30", "output": "30"}],
        "starter_code": "def get_setting(settings, key, default):\n    # Write your solution here\n    pass",
        "solution_code": "def get_setting(settings, key, default):\n    return settings.get(key, default)",
        "test_cases": [{"args": [{"mode": "test"}, "timeout", 30], "expected": 30}, {"args": [{"mode": "test"}, "mode", "dev"], "expected": "test"}],
        "hints": ["Dictionaries have a method for a lookup with a fallback.", "The fallback should only be used when the key is missing.", "Use settings.get with key and default."],
        "tags": ["dictionaries", "functions"], "function_name": "get_setting",
    },
    "Tuple unpacking": {
        "prompt": "Write a function that returns values with the first and last items swapped.",
        "examples": [{"input": "values = [1, 2, 3, 4]", "output": "[4, 2, 3, 1]"}],
        "starter_code": "def swap_ends(values):\n    # Write your solution here\n    pass",
        "solution_code": "def swap_ends(values):\n    result = values.copy()\n    result[0], result[-1] = result[-1], result[0]\n    return result",
        "test_cases": [{"args": [[1, 2, 3, 4]], "expected": [4, 2, 3, 1]}, {"args": [[9, 2]], "expected": [2, 9]}],
        "hints": ["Make a copy so the original list stays unchanged.", "Indexes 0 and -1 refer to the first and last items.", "Assign both indexed values in one statement."],
        "tags": ["lists", "indexes", "functions"], "function_name": "swap_ends",
    },
    "Generator expression": {
        "prompt": "Write a function that returns a list of non-empty lines after stripping whitespace.",
        "examples": [{"input": "lines = [' one ', '', ' two']", "output": "['one', 'two']"}],
        "starter_code": "def clean_lines(lines):\n    # Write your solution here\n    pass",
        "solution_code": "def clean_lines(lines):\n    return [line.strip() for line in lines if line.strip()]",
        "test_cases": [{"args": [[" one ", "", " two"]], "expected": ["one", "two"]}, {"args": [["  ", "ok"]], "expected": ["ok"]}],
        "hints": ["Each line needs two decisions: clean it, then check whether it has content.", "Use strip() and a condition in a loop or comprehension.", "Strip first and include the result only when the stripped text is non-empty."],
        "tags": ["lists", "strings", "conditions"], "function_name": "clean_lines",
    },
}

for question in QUESTIONS:
    exercise = BEGINNER_EXERCISES.get(question["title"])
    if exercise:
        question.update(exercise)
    else:
        question.update({
            "examples": [], "starter_code": "", "solution_code": question["answer"],
            "test_cases": [], "hints": ["Break the task into one small step at a time."],
            "tags": [question["section"], question["difficulty"]], "function_name": "",
        })

assert len(QUESTIONS) == 300
assert all(sum(q["section"] == section and q["difficulty"] == level for q in QUESTIONS) == count
           for section in ("python", "sql", "vba")
           for level, count in (("easy", 50), ("medium", 30), ("hard", 20)))
